local function has_config_key(key)
    local ok, _, err = pcall(hl.get_config, key)
    return ok and err == nil
end

if has_config_key("plugin.hycov.overview_gappo") then
    hl.config({
        plugin = {
            hycov = {
            overview_gappo = 100,
            overview_gappi = 50,
            enable_hotarea = 1,
            hotarea_monitor = "all",
            hotarea_pos = 1,
            hotarea_size = 10,
            swipe_fingers = 4,
            move_focus_distance = 100,
            enable_gesture = 1,
            disable_workspace_change = 0,
            disable_spawn = 0,
            auto_exit = 1,
            auto_fullscreen = 0,
            only_active_workspace = 0,
            only_active_monitor = 0,
            enable_alt_release_exit = 1,
            -- alt_replace_key = "Alt_L",
            alt_toggle_auto_next = 1,
            click_in_cursor = 1,
            height_of_titlebar = 0,
        },
        },
    })
end

