local mainMod = "SUPER"

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + W", hl.dsp.window.close())
hl.bind(mainMod .. " + ALT + Q", hl.dsp.exit())
hl.bind(mainMod .. " + SHIFT + ESCAPE", hl.dsp.exec_cmd("$HOME/PATH/launch_waybar.sh"))
-- hl.bind(mainMod .. " + SHIFT + RETURN", hl.dsp.exec_cmd("$HOME/PATH/lock_screen_off.sh"))
hl.bind(mainMod .. " + SHIFT + RETURN", hl.dsp.exec_cmd("loginctl lock-session"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("kitty -e yazi"))
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("pcmanfm-qt"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("firefox"))
hl.bind(mainMod .. " + I", hl.dsp.exec_cmd("thunderbird"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("vesktop")) -- Discord client.
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd("rofi -show drun -location 0 -theme ~/.config/rofi/themes/Serenity -config ~/.config/rofi/config -show-icons"))
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.exec_cmd("DRI_PRIME=pci-0000_01_00_0 __VK_LAYER_NV_optimus=NVIDIA_only __GLX_VENDOR_LIBRARY_NAME=nvidia rofi -show drun -xoffset 100 -yoffset 200 -theme ~/.config/rofi/themes/Serenity -show-icons"))
hl.bind(mainMod .. " + ESCAPE", hl.dsp.exec_cmd("killall wlogout; wlogout"))
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("qalculate-gtk"))
-- hl.bind(mainMod .. " + SUPER_L", hl.dsp.exec_cmd("rofi -show drun -theme ~/.config/rofi/themes/launchpad.rasi -config ~/.config/rofi/config-launchpad -show-icons"), { release = true })
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo()) -- dwindle.
hl.bind(mainMod .. " + F", hl.dsp.layout("togglesplit")) -- dwindle.
hl.bind(mainMod .. " + T", hl.dsp.workspace.toggle_special("scratchpad"))
hl.bind(mainMod .. " + F11", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
-- Legacy plugin dispatchers kept as comments from hyprland.conf.
-- bind = ALT, tab, hycov:toggleoverview
-- hl.bind("ALT + tab", hl.dsp.workspace.toggle_special("overview"))
-- hl.bind("ALT + tab", hl.dsp.focus({ workspace = "e+1" }))
-- hl.bind("ALT + tab", hl.dsp.exec_cmd("sleep 1 && hyprctl dispatch overview:close"), { release = true })
-- bind = ALT + SHIFT, tab, overview:open
-- hl.bind("ALT + SHIFT + tab", hl.dsp.focus({ workspace = "e-1" }))
-- hl.bind("ALT + SHIFT + tab", hl.dsp.exec_cmd("sleep 1 && hyprctl dispatch overview:close"), { release = true })

-- Move focus with mainMod + vim keys.
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "l" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "r" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "d" }))

-- Cycle focus with mainMod + C and mainMod + SHIFT + C.
hl.bind(mainMod .. " + C", hl.dsp.window.cycle_next())
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.window.cycle_next({ next = false }))

-- Move windows with mainMod + vim keys.
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "d" }))

-- Window grouping.
hl.bind(mainMod .. " + G", hl.dsp.group.toggle())
hl.bind(mainMod .. " + ALT + H", hl.dsp.window.move({ into_group = "l" }))
hl.bind(mainMod .. " + ALT + L", hl.dsp.window.move({ into_group = "r" }))
hl.bind(mainMod .. " + ALT + K", hl.dsp.window.move({ into_group = "u" }))
hl.bind(mainMod .. " + ALT + J", hl.dsp.window.move({ into_group = "d" }))
hl.bind(mainMod .. " + TAB", hl.dsp.group.next())
hl.bind(mainMod .. " + SHIFT + TAB", hl.dsp.group.prev())
hl.bind(mainMod .. " + ALT + SHIFT + H", hl.dsp.window.move({ out_of_group = "l" }))
hl.bind(mainMod .. " + ALT + SHIFT + L", hl.dsp.window.move({ out_of_group = "r" }))
hl.bind(mainMod .. " + ALT + SHIFT + K", hl.dsp.window.move({ out_of_group = "u" }))
hl.bind(mainMod .. " + ALT + SHIFT + J", hl.dsp.window.move({ out_of_group = "d" }))

-- Window resizing.
hl.bind(mainMod .. " + CTRL + H", hl.dsp.window.resize({ x = -50, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + L", hl.dsp.window.resize({ x = 50, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + K", hl.dsp.window.resize({ x = 0, y = -50, relative = true }))
hl.bind(mainMod .. " + CTRL + J", hl.dsp.window.resize({ x = 0, y = 50, relative = true }))

-- Switch workspaces with mainMod + [0-9].
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end
-- hl.bind(mainMod .. " + T", hl.dsp.focus({ workspace = "special" }))
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.window.move({ workspace = "special:scratchpad" }))

-- Move active window to a workspace with mainMod + Keypad [0-9].
hl.bind(mainMod .. " + KP_End", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + KP_Down", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + KP_Next", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + KP_Left", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + KP_Begin", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + KP_Right", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + KP_Home", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + KP_Up", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + KP_Prior", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + KP_Insert", hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mainMod + SHIFT + Keypad [0-9].
hl.bind(mainMod .. " + SHIFT + KP_End", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + KP_Down", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + KP_Next", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + KP_Left", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + KP_Begin", hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + SHIFT + KP_Right", hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + SHIFT + KP_Home", hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + SHIFT + KP_Up", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + SHIFT + KP_Prior", hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + SHIFT + KP_Insert", hl.dsp.window.move({ workspace = 10 }))

-- Scroll through existing workspaces with mainMod + scroll.
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging.
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Volume and media control.
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("$HOME/PATH/volume.sh --inc"), { repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("$HOME/PATH/volume.sh --dec"), { repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("$HOME/PATH/volume.sh --toggle-mic"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("$HOME/PATH/volume.sh --toggle"))
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"))

-- Display backlight control from keyboard made for Windows/Linux.
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("$HOME/PATH/backlight.sh --inc"))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("$HOME/PATH/backlight.sh --dec"))
-- Display backlight control from keyboard made for Mac.
hl.bind("XF86Launch5", hl.dsp.exec_cmd("$HOME/PATH/backlight.sh --dec"), { repeating = true })
hl.bind("XF86Launch6", hl.dsp.exec_cmd("$HOME/PATH/backlight.sh --inc"), { repeating = true })

-- Additional applications.
-- zsh -i workaround for nvim to detect path from .zshrc.
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd('kitty -e zsh -i -c "nvim"'))
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("emacs"))
-- Emoji menu.
hl.bind(mainMod .. " + EQUAL", hl.dsp.exec_cmd("rofimoji --action copy clipboard"))
-- Clipboard history.
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("rofi -modi clipboard:$HOME/PATH/cliphist-rofi.sh -show clipboard -theme ~/.config/rofi/themes/Serenity -show-icons"))
-- Delete from clipboard history.
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("cliphist list| rofi -dmenu -theme ~/.config/rofi/themes/Serenity -show-icons | cliphist delete"))

-- Swaync key binds.
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("swaync-client -t"))

-- Screenshot.
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("grimblast --notify copysave screen"))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd("grimblast --notify copysave area"))
hl.bind("Print", hl.dsp.exec_cmd("grimblast --notify copysave screen"))

-- mpdevil.
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("mpdevil"))

-- Hints for keyboard navigation.
-- Waybar needs to be killed as it offsets hints layer.
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("$HOME/.local/bin/hints"))
